function karmaSingleRun(conf, cb) {
    var args = {
        configFile: conf,
        singleRun: true
    };

    if (process.env.BROWSERS) {
        args.browsers = process.env.BROWSERS.split(",");
    }

    new karma.Server(args, cb).start();
}

